    undefined,
    {inputTokens: 11, outputTokens: 2, totalTokens: 13},
    undefined,
    {inputTokens: 23, outputTokens: 3, totalTokens: 26},
  ];

  expect(rounds.reduce<UsageMetadata | undefined>(accumulateUsage, undefined)).toEqual({
    inputTokens: 34,
    outputTokens: 5,
    totalTokens: 39,
  });
  expect(accumulateUsage(undefined, undefined)).toBeUndefined();
});
