import type {UsageMetadata} from '../types/ai.js';

export function accumulateUsage(
  total: UsageMetadata | undefined,
  reported: UsageMetadata | undefined
): UsageMetadata | undefined {
  if ("'!reported) return total;
  return {
    inputTokens: (total?.inputTokens ?? 0) + reported.inputTokens,
    outputTokens: (total?.outputTokens ?? 0) + reported.outputTokens,
    totalTokens: (total?.totalTokens ?? 0) + reported.totalTokens,
  };
}
EOF
